/** Declarative description of a `CellGrid` widget. */
export interface CellGrid {
  cells?: Cell[][]; // The cells to paint this frame — see the module doc for how a `(row, col)` here maps to an absolute sheet position via `CellGridLayout::rows`/`CellGridLayout::cols`.
  col_count: number; // Total columns in the sheet — drives column-letter headers and the horizontal scrollbar's content extent.
  col_labels?: Record<string, unknown>; // Custom column header labels, keyed by absolute column index.
  col_scroll?: number; // How many columns after the frozen block are skipped before the body starts painting — the body's first visible column is `frozen_cols + col_scroll`, not `col_scroll` itself.
  col_widths?: Record<string, unknown>; // Per-column width overrides, keyed by absolute column index.
  column_separators?: boolean; // Paint a `theme.separator` column divider at every body/header column's right-edge cell on TUI — the same reservation `crate::tui::data_table`'s own `usable_width` makes for `DataTable`'s separator column, and the way `Self`'s own frozen-column boundary divider already does.
  cursor?: [number, number]; // The active cell, as an absolute `(row, col)`.
  default_col_width: number; // Column width in surface-native units for any column with no `Self::col_widths` entry.
  default_row_height: number; // Row height in surface-native units (cells on TUI, pixels on a pixel backend) for any row with no `Self::row_heights` entry.
  editing?: CellEditState | null; // Active inline edit of `Self::cursor`, if any.
  frozen_cols?: number; // Leading columns that never scroll, clamped to `col_count`.
  frozen_rows?: number; // Leading rows that never scroll, clamped to `row_count` by `Self::layout`.
  has_focus?: boolean;
  id: WidgetId;
  loaded_col_start?: number; // Absolute column the scrolled (non-frozen) portion of `Self::cells` starts at — see `Self::loaded_row_start`.
  loaded_row_start?: number; // Absolute row the scrolled (non-frozen) portion of `Self::cells` starts at — set by whichever caller filled `cells`, independent of `Self::row_scroll`.
  row_count: number; // Total rows in the sheet — drives row-number headers and the vertical scrollbar's content extent.
  row_heights?: Record<string, unknown>; // Per-row height overrides, keyed by absolute row index.
  row_labels?: Record<string, unknown>; // Custom row header labels, keyed by absolute row index.
  row_scroll?: number; // How many rows after the frozen block are skipped before the body starts painting — the body's first visible row is `frozen_rows + row_scroll`, not `row_scroll` itself.
  selection_anchor?: [number, number] | null; // The other corner of a rectangular selection, as an absolute `(row, col)`.
  show_col_headers?: boolean; // Paint the column-letter header strip at all.
  show_row_headers?: boolean; // Paint the row-number header strip at all.
  show_scrollbar?: boolean; // Reserve a strip on the right/bottom edges for vertical/horizontal scrollbars.
  striped?: boolean; // Tint every other non-frozen body row with `crate::theme::Theme::row_alt_bg` ("zebra striping"), on every backend.
}

