/** Orientation of a scrollbar. */
export type ScrollAxis = "Vertical" | "Horizontal";

export type ScrollAxisValue = "vertical" | "horizontal";

/** Scroll-wheel delta. Positive `y` = scroll up (toward the top of content). Backends that report scroll in lines/cells/pixels normalise to their native unit before emitting. */
export interface ScrollDelta {
  x: number;
  y: number;
}

/** Scroll model for a `MultiSectionView`. */
export type ScrollMode = "PerSection" | "WholePanel";

/** Declarative scroll-offset state for a generic scrollable region. */
export interface ScrollView {
  axis?: ScrollAxis;
  content_len: number; // Total scrollable extent of the child content, in the host's own units (rows, wrapped lines, pixels — see the module doc).
  focused?: boolean; // Whether this view currently holds keyboard focus.
  id: WidgetId;
  scroll_offset?: number; // First visible content unit.
  viewport: Rect; // The clip region, in surface-native units.
}

/** Semantic event produced by `ScrollView::handle_wheel`, `ScrollView::handle_key`, or `ScrollView::scroll_by`. */
export type ScrollViewEvent = { Scrolled: _ScrollViewEventScrolled; };

/** Declarative description of a scrollbar. */
export interface Scrollbar {
  axis: ScrollAxis;
  dragging?: boolean; // User is actively dragging the thumb — rasterisers may apply an even brighter / fully opaque highlight.
  hovered?: boolean; // Cursor is hovering over the scrollbar — rasterisers may brighten the thumb.
  id: WidgetId;
  thumb_len: number;
  thumb_start: number;
  track: Rect;
}

/** One section in a `MultiSectionView`. */
export interface Section {
  aux?: SectionAux | null; // Optional widget rendered between header and body (commit input, search, toolbar).
  body: SectionBody;
  collapsed?: boolean;
  header: SectionHeader;
  id: string;
  max_size?: number | null; // Ceiling on resolved size in main-axis units.
  min_size?: number | null; // Floor on resolved size in main-axis units (after sizing strategy is applied).
  size: SectionSize;
}

/** Auxiliary widget rendered between a section's header and its body. */
export type SectionAux = { Input: InlineInput; } | { Toolbar: HeaderAction[]; } | { Search: InlineInput; } | { Custom: WidgetId; };

/** Body content of a section. Composes existing quadraui primitives; `Custom` is the escape hatch for app-defined widgets the rasteriser can't paint (host paints in returned `SectionLayout::body_bounds`). */
export type SectionBody = { Tree: TreeView; } | { List: ListView; } | { Form: Form; } | { Terminal: Terminal; } | { MessageList: MessageList; } | { Text: StyledText[]; } | { Chart: Chart; } | { Empty: EmptyBody; } | { Custom: WidgetId; };

/** Header row content for a section. */
export interface SectionHeader {
  actions?: HeaderAction[]; // Right-aligned action buttons.
  badge?: StyledText | null; // Right-of-title status indicator (e.g.
  icon?: Icon | null;
  show_chevron?: boolean; // Whether to draw the leading chevron (▾/▸).
  title: StyledText;
}

/** Sizing strategy for a single section along the main axis. */
export type SectionSize = ("Content" | "EqualShare") | _SectionSizeDict;

/** A standalone single-choice option picker. */
export interface Select {
  disabled?: boolean; // A disabled select paints dimmed and ignores every gesture.
  focused?: boolean; // Whether to paint the focused-row wash.
  id: WidgetId;
  options: string[]; // The options, in order.
  selected_idx?: number; // The chosen option's index into `options`.
}

/** Visual-selection mode. */
export type SelectionKind = "Char" | "Line" | "Block";

/** Selection behaviour for row-oriented widgets (`TreeView`, `ListView`, `DataTable`). */
export type SelectionMode = "None" | "Single" | "Multi";

/** One data series in a chart. */
export interface Series {
  color?: Color | null; // Override colour.
  data: number[]; // Y-values, evenly spaced along the x-axis.
  fill?: boolean; // Fill the area under the line with a translucent wash of the series colour on pixel backends, and with braille dots down to the plot floor on TUI (`ChartKind::Line` only; ignored for Sparkline and the bar kinds).
  label: string;
}

/** `run_shell`'s `config` dict. */
export interface ShellConfigDescriptor {
  activity_bar_width?: number | null;
  bottom_items?: PanelDefinitionDescriptor[] | null;
  bottom_panel?: BottomPanelConfigDescriptor | null;
  bottom_panel_height_lh?: number | null;
  default_sidebar_width?: number | null;
  has_bottom_panel?: boolean | null;
  has_command_line?: boolean | null;
  has_status_bar?: boolean | null;
  has_title_bar?: boolean | null;
  max_sidebar_width?: number | null;
  min_sidebar_width?: number | null;
  panels?: PanelDefinitionDescriptor[] | null;
  position?: SidebarPositionValue | null;
  sidebar_visible?: boolean | null;
  title: string;
  title_bar_height_lh?: number | null;
}

/** Semantic events emitted by `ShellView::handle_event`. */
export type ShellEvent = ("SidebarHidden" | "BottomPanelHidden" | "Consumed" | "Ignored") | _ShellEventDict;

/** Side of an `Anchor`'s `rect` that an overlay prefers to open on. */
export type Side = "Top" | "Bottom" | "Left" | "Right" | "AtPoint";

/** What a `Sidebar` reports. */
export type SidebarAction = { HeaderActivated: _SidebarActionHeaderActivated; } | { ActiveSectionChanged: _SidebarActionActiveSectionChanged; } | { CollapseChanged: _SidebarActionCollapseChanged; } | { RowSelected: _SidebarActionRowSelected; } | { RowActivated: _SidebarActionRowActivated; } | { RowToggleExpand: _SidebarActionRowToggleExpand; } | { ContextMenuRequested: _SidebarActionContextMenuRequested; } | { ScrollChanged: _SidebarActionScrollChanged; } | { PanelScrolled: _SidebarActionPanelScrolled; } | { EditChanged: _SidebarActionEditChanged; } | { EditConfirmed: _SidebarActionEditConfirmed; } | { EditCancelled: _SidebarActionEditCancelled; } | { Form: _SidebarActionForm; };

export type SidebarPositionValue = "left" | "right";

/** A standalone numeric slider over `[min, max]`. */
export interface Slider {
  disabled?: boolean; // A disabled slider paints dimmed and ignores every gesture.
  focused?: boolean; // Whether to paint the focused-row wash.
  id: WidgetId;
  max: number; // The high end of the range.
  min: number; // The low end of the range.
  step?: number; // How far one arrow key moves the value.
  value: number; // The current value.
}

/** Sort direction indicator for column headers. */
export type SortDirection = "Ascending" | "Descending";

/** Misspelled-word span on one line — drives spell-check underline. */
export interface SpellMark {
  end_col: number;
  start_col: number;
}

/** Declarative description of an indeterminate spinner. */
export interface Spinner {
  accent?: Color | null; // Optional accent colour for the glyph.
  frame_idx?: number; // Animation frame index.
  id: WidgetId;
  label?: string; // Label shown next to the spinner, e.g.
}

/** Orientation of a `Split`. */
export type SplitDirection = "Horizontal" | "Vertical";

/** One `"split_tree"` node: a `{"leaf": <node>}` pane or a nested `{"split": {...}}`. */
export type SplitTreeNode = { leaf: LayoutNode; } | { split: SplitTreeSplitPayload; };

export interface SplitTreeSplitPayload {
  first: SplitTreeNode;
  orientation: OrientationValue;
  ratio: number;
  second: SplitTreeNode;
}

/** Status of a single pipeline stage. */
export type StageStatus = "Pending" | "Active" | "Done" | "Failed" | "Skipped" | "Stale";

/** Declarative description of a status bar. */
export interface StatusBar {
  id: WidgetId;
  left_segments: StatusBarSegment[]; // Left-aligned segments, **most-important first**: a narrow bar squeezes and then drops from the end.
  right_segments: StatusBarSegment[]; // Right-aligned segments, **most-important last**: a narrow bar drops from the front.
}

/** Events a `StatusBar` emits back to the app. */
export type StatusBarEvent = { SegmentClicked: _StatusBarEventSegmentClicked; } | { KeyPressed: _StatusBarEventKeyPressed; };

/** One styled segment in a `StatusBar`. */
export interface StatusBarSegment {
  action_id?: WidgetId | null; // `None` = non-interactive.
  bg: Color;
  bold?: boolean;
  fg: Color;
  text: string;
}

/** Per-span text style used by the editor's byte-range `EditorStyledSpan`. Mirrors `vimcode::render::Style`, with `font_scale` narrowed from `f64` → `f32` so derives of `PartialEq` / `Serialize` work without `Eq` blocking us. */
export interface Style {
  bg?: Color | null;
  bold?: boolean;
  fg: Color;
  font_scale: number; // Font scale factor (1.0 = normal).
  italic?: boolean;
}

/** A `"style"` colour token: a `Color` object, or a `"#rrggbb"` / `"#rrggbbaa"` hex string. */
export type StyleColorValue = Color | string;

/** A node's `"style"` override, scoped to its subtree: every `Theme` colour token and `Style` metric token is an optional key (with `bg`/`fg`/`border`/`accent` aliasing `Theme::background`/`foreground`/`border_fg`/`accent_fg`), plus the font keys and the `hover`/`pressed`/`focus` interaction-state branches. */
export interface StyleValue {
  accent?: StyleColorValue | null;
  accent_bg?: StyleColorValue | null;
  activity_bar_width?: number | null;
  annotation_fg?: StyleColorValue | null;
  backdrop_opacity?: number | null;
  badge_blocked?: StyleColorValue | null;
  badge_passed?: StyleColorValue | null;
  badge_running?: StyleColorValue | null;
  badge_warning?: StyleColorValue | null;
  bg?: StyleColorValue | null;
  board_col_header_bg?: StyleColorValue | null;
  board_selected_card_bg?: StyleColorValue | null;
  border?: StyleColorValue | null;
  border_width?: number | null;
  bracket_match_bg?: StyleColorValue | null;
  button_radius?: number | null;
  card_hint_bg?: StyleColorValue | null;
  card_hint_fg?: StyleColorValue | null;
  colorcolumn_bg?: StyleColorValue | null;
  command_line_bg?: StyleColorValue | null;
  command_line_fg?: StyleColorValue | null;
  completion_bg?: StyleColorValue | null;
  completion_border?: StyleColorValue | null;
  completion_fg?: StyleColorValue | null;
  completion_selected_bg?: StyleColorValue | null;
  control_height?: number | null;
  corner_radius?: number | null;
  cursor?: StyleColorValue | null;
  cursor_normal_alpha?: number | null;
  cursorline_bg?: StyleColorValue | null;
  dap_stopped_bg?: StyleColorValue | null;
  diagnostic_error?: StyleColorValue | null;
  diagnostic_hint?: StyleColorValue | null;
  diagnostic_info?: StyleColorValue | null;
  diagnostic_warning?: StyleColorValue | null;
  diff_added_bg?: StyleColorValue | null;
  diff_padding_bg?: StyleColorValue | null;
  diff_removed_bg?: StyleColorValue | null;
  editor_active_background?: StyleColorValue | null;
  error_fg?: StyleColorValue | null;
  fg?: StyleColorValue | null;
  focus?: StyleValue | null;
  focus_ring_width?: number | null;
  font_family?: string | null;
  font_size?: number | null;
  font_weight?: FontWeightValue | null;
  ghost_text_fg?: StyleColorValue | null;
  git_added?: StyleColorValue | null;
  git_deleted?: StyleColorValue | null;
  git_modified?: StyleColorValue | null;
  header_bg?: StyleColorValue | null;
  header_fg?: StyleColorValue | null;
  hover?: StyleValue | null;
  hover_bg?: StyleColorValue | null;
  hover_border?: StyleColorValue | null;
  hover_fg?: StyleColorValue | null;
  inactive_fg?: StyleColorValue | null;
  inactive_selected_bg?: StyleColorValue | null;
  indent_guide_active_fg?: StyleColorValue | null;
  indent_guide_fg?: StyleColorValue | null;
  input_bg?: StyleColorValue | null;
  lightbulb?: StyleColorValue | null;
  line_number_active_fg?: StyleColorValue | null;
  line_number_fg?: StyleColorValue | null;
  link_fg?: StyleColorValue | null;
  list_cell_overflow?: CellOverflowValue | null;
  match_fg?: StyleColorValue | null;
  muted_fg?: StyleColorValue | null;
  padding?: number | null;
  pressed?: StyleValue | null;
  query_fg?: StyleColorValue | null;
  row_height?: number | null;
  row_padding_x?: number | null;
  scrollbar_thumb?: StyleColorValue | null;
  scrollbar_track?: StyleColorValue | null;
  scrollbar_width?: number | null;
  selected_bg?: StyleColorValue | null;
  selection?: StyleColorValue | null;
  selection_alpha?: number | null;
  selection_bg?: StyleColorValue | null;
  separator?: StyleColorValue | null;
  shadow_elevation?: number | null;
  spell_error?: StyleColorValue | null;
  status_bar_cell_gap?: number | null;
  status_bar_cell_overflow?: CellOverflowValue | null;
  status_bar_height?: number | null;
  surface_bg?: StyleColorValue | null;
  surface_fg?: StyleColorValue | null;
  tab_active_bg?: StyleColorValue | null;
  tab_active_fg?: StyleColorValue | null;
  tab_bar_bg?: StyleColorValue | null;
  tab_height?: number | null;
  tab_inactive_fg?: StyleColorValue | null;
  tab_padding_x?: number | null;
  tab_preview_active_fg?: StyleColorValue | null;
  tab_preview_inactive_fg?: StyleColorValue | null;
  title_fg?: StyleColorValue | null;
  toolbar_height?: number | null;
  tooltip_auto_dismiss_ms?: number | null;
  tooltip_delay_ms?: number | null;
  warning_fg?: StyleColorValue | null;
  yank_highlight_alpha?: number | null;
  yank_highlight_bg?: StyleColorValue | null;
}

/** A contiguous run of text sharing a single style. */
export interface StyledSpan {
  bg?: Color | null;
  bold?: boolean;
  fg?: Color | null;
  italic?: boolean;
  text: string;
  underline?: boolean;
}

/** A sequence of styled spans rendered inline on one line. */
export interface StyledText {
  spans: StyledSpan[];
}

/** Declarative description of a standalone on/off switch. */
export interface Switch {
  disabled?: boolean; // When `true`, `Switch::handle_key` and `Switch::click` both return `None` — same "disabled means inert, not hidden" contract every other primitive's `disabled` flag follows.
  focused?: boolean; // Whether this switch currently holds keyboard focus.
  id: WidgetId;
  value?: boolean; // Current on/off state.
}

/** The OS-level theme preference `PlatformServices::system_theme` reports — light/dark, accent colour, and high-contrast. */
export interface SystemTheme {
  accent?: Color | null; // The OS accent colour, when the platform exposes one and the backend can read it.
  dark: boolean; // `true` when the OS is set to a dark appearance (Windows "Dark" app mode, macOS Dark Appearance, GTK's `prefer-dark-theme`, or — on TUI — `COLORFGBG`'s background index reads as dark).
  high_contrast: boolean; // `true` when the OS high-contrast accessibility setting is active (Windows High Contrast mode, GTK's `HighContrast*` theme names).
  reduce_motion?: boolean; // `true` when the OS "reduce motion" accessibility preference is active (macOS `accessibilityDisplayShouldReduceMotion`, Windows `SPI_GETCLIENTAREAANIMATION` inverted, GTK's `gtk-enable-animations` inverted).
}

/** Declarative description of a tab bar. */
export interface TabBar {
  active_accent?: Color | null; // Optional colour used to underline the active tab's filename portion.
  chrome?: TabChrome; // Active-tab framing and keyboard-focus request for this bar — the decoration `crate::primitive::Primitive::paint` / `crate::primitive::Primitive::paint_cells` draw around the active tab, and the tab index they paint the focus-visible treatment on.
  compact?: boolean; // When `true`, the GTK rasteriser uses minimal padding (2px) and zero gap between tabs.
  glyphs?: TabBarGlyphs; // Close / dirty glyph overrides for every tab in this bar.
  icons?: (TabIcon | null)[]; // Optional per-tab leading icons, index-aligned with `Self::tabs`.
  id: WidgetId;
  right_segments?: TabBarSegment[]; // Right-aligned trailing segments, drawn in order from left to right starting at `bar_width - sum(widths)`.
  scroll_offset?: number; // Index of the first visible tab when tabs overflow.
  show_tab_close?: boolean; // When `false`, per-tab close buttons (×/●) are suppressed — the measurer returns `close_width: 0.0` and rasterisers skip the glyph.
  tabs: TabItem[];
}

/** Events a `TabBar` emits back to the app. Currently unused by vimcode (click path goes through the engine's `TabBarClickTarget` enum), but defined for plugin invariants §10 — plugin-declared tab bars will consume events directly. */
export type TabBarEvent = { TabActivated: _TabBarEventTabActivated; } | { TabClosed: _TabBarEventTabClosed; } | { ButtonClicked: _TabBarEventButtonClicked; } | { KeyPressed: _TabBarEventKeyPressed; } | { FocusMoved: _TabBarEventFocusMoved; };

/** Optional app-supplied override for the close and dirty (unsaved) marks a tab bar paints. */
export interface TabBarGlyphs {
  close?: Icon | null;
  dirty?: Icon | null;
}

/** One right-aligned segment in a `TabBar`. Either a clickable button (with an `id`) or a non-interactive label (`id = None`). */
export interface TabBarSegment {
  id?: WidgetId | null; // `None` = non-interactive.
  is_active?: boolean; // Highlighted (toggled-on) state, e.g.
  text: string; // Text / icon glyph to render (e.g.
  width_cells: number;
}

/** Per-bar chrome request: which active-tab frame a backend should paint. Carried by `TabBar::chrome`, so it reaches both `crate::primitive::Primitive::layout` (which reserves the frame's extra width) and the painters. */
export interface TabChrome {
  active_frame?: TabFrame; // Which frame to paint around the active tab.
  focused_index?: number | null; // Index into `TabBar::tabs` of the keyboard-focused tab, if any.
  separator?: TabSeparator; // What the cell-grid painter puts after a tab with no close glyph.
}

/** A position-based drop instruction: the result of resolving a tab drag-and-drop gesture against pane geometry, expressed purely as indices and a split direction — never as a mutation applied to an owned model. */
export type TabDropInstruction = "NoOp" | _TabDropInstructionDict;

/** Active-tab framing vocabulary: which decoration, if any, should enclose the active tab's full content — label *and* close glyph. */
export type TabFrame = "None" | "Brackets";

/** What a `TabGroup` reports, and what `TabGroup::apply` answers after applying it. */
export type TabGroupEvent = { TabActivated: _TabGroupEventTabActivated; } | { TabClosed: _TabGroupEventTabClosed; } | { PaneCollapsed: _TabGroupEventPaneCollapsed; } | { PaneAdded: _TabGroupEventPaneAdded; } | { PaneFocused: _TabGroupEventPaneFocused; } | { DividerResized: _TabGroupEventDividerResized; } | { NewTabRequested: _TabGroupEventNewTabRequested; } | { TabDropped: _TabGroupEventTabDropped; } | { TabReordered: _TabGroupEventTabReordered; } | { TabMovedToPane: _TabGroupEventTabMovedToPane; } | { TabSplitToNewPane: _TabGroupEventTabSplitToNewPane; };

/** `TabIcon`'s two accepted wire shapes, `Codicon` first for the same reason as `crate::Icon`'s. */
export type TabIcon = _TabIcon1 | _TabIcon2;

/** One tab in a `TabBar`. */
export interface TabItem {
  is_active?: boolean;
  is_closable?: boolean; // When `true`, this tab renders an individual `×` / `●` close button (subject to `TabBar::show_tab_close` also being `true`).
  is_dirty?: boolean;
  is_preview?: boolean;
  label: string; // Display label, e.g.
}

/** What a cell-grid tab bar paints after a tab that has no close glyph (`show_tab_close: false`, or a non-closable tab) and no bracket frame. */
export type TabSeparator = "Rule" | "None";

/** Declarative description of a terminal cell grid. */
export interface Terminal {
  cells: TerminalCell[][];
  id: WidgetId;
  scrollbar?: TerminalScrollbar | null; // When present, the terminal paints a themed vertical `crate::Scrollbar` in a gutter at its right edge.
}

/** One styled cell in a `Terminal`. Carries the rendered grapheme cluster, RGB foreground/background, attributes, and overlay flags (cursor / selection / find match) that the backend interprets visually. */
export interface TerminalCell {
  bg: Color;
  bold?: boolean;
  cursor_blinking?: boolean; // `true` when the child requested a *blinking* DECSCUSR variant (odd `Ps` values `1`/`3`/`5`) rather than steady (`2`/`4`/`6`).
  cursor_shape?: TerminalCursorShape; // Shape of the VT100 cursor at this cell, from the child program's most recent DECSCUSR request (`ESC [ Ps SP q`) — see `crate::terminal_engine::TerminalSession::cursor_shape`.
  dim?: boolean; // SGR 2 (faint/dim) — `vt100::Cell::dim()`.
  fg: Color;
  is_cursor?: boolean; // Cell holds the VT100 cursor position.
  is_find_active?: boolean; // Cell is part of the currently-selected find match (bright highlight).
  is_find_match?: boolean; // Cell is part of a non-active find match (dim highlight).
  italic?: boolean;
  selected?: boolean; // Cell is part of the user's mouse selection.
  text: string; // The cell's full grapheme cluster — a base character plus any combining marks (accents, etc.) vt100 appended to it, e.g.
  underline?: boolean;
}

/** Shape of the VT100 cursor, as steered by the child program's DECSCUSR (`ESC [ Ps SP q`) request — see `crate::terminal_engine::TerminalSession::cursor_shape`. */
export type TerminalCursorShape = "Block" | "Underline" | "Bar";

/** Events a `Terminal` emits back to the app, as `crate::UiEvent::Terminal`. Its `crate::interactive::Interactive` impl produces the selection and scroll variants; the app applies them to its own session (e.g. `TerminalEvent::Scroll` through the engine's `handle_wheel`, which decides between forwarding the wheel to the child and scrolling local history). */
export type TerminalEvent = "SelectEnd" | _TerminalEventDict;

/** Scrollbar state for a `Terminal`. Paint builds a `crate::Scrollbar::vertical` from these values on the gutter `TerminalLayout::scrollbar` reserved, and paints it with the scrollbar's own painter. */
export interface TerminalScrollbar {
  inverted?: boolean; // When `true`, `scroll_offset = 0` means "at the bottom" (live view) and increasing offset scrolls up into history.
  scroll_offset: number;
  total_lines: number;
  visible_lines: number;
  width?: number | null; // Scrollbar width in surface-native units (pixels on a pixel backend, cells on TUI).
}

/** `TextArea`'s wire shape: the whole value as one string with `'/n'` line breaks and a caret byte offset. */
export interface TextArea {
  cursor?: number | null;
  has_focus?: boolean;
  id: WidgetId;
  placeholder?: string | null;
  value?: string;
  visible_rows?: number;
}

/** Declarative description of a `TextDisplay`. */
export interface TextDisplay {
  auto_scroll?: boolean; // When true, backends auto-scroll to keep the latest line visible.
  has_focus?: boolean;
  id: WidgetId;
  lines: TextDisplayLine[];
  max_lines?: number; // Maximum lines to retain in the ring buffer.
  scroll_offset?: number; // Index of the first visible line.
  show_scrollbar?: boolean; // When true, a vertical scrollbar is rendered at the trailing edge of the viewport.
  title?: StyledText | null; // Optional title row painted above the body.
}

/** Events a `TextDisplay` emits back to the app. */
export type TextDisplayEvent = { Scrolled: _TextDisplayEventScrolled; } | { AutoScrollToggled: _TextDisplayEventAutoScrollToggled; } | { Copied: _TextDisplayEventCopied; } | { KeyPressed: _TextDisplayEventKeyPressed; };

export interface TextDisplayLeaf {
  auto_scroll?: boolean; // When true, backends auto-scroll to keep the latest line visible.
  has_focus?: boolean;
  id: WidgetId;
  lines: TextDisplayLine[];
  max_lines?: number; // Maximum lines to retain in the ring buffer.
  scroll_offset?: number; // Index of the first visible line.
  show_scrollbar?: boolean; // When true, a vertical scrollbar is rendered at the trailing edge of the viewport.
  title?: StyledText | null; // Optional title row painted above the body.
  items_window?: ItemsWindow | null;
}

/** One line in a `TextDisplay`. Carries styled spans plus an optional decoration tag (Error/Warning/Muted/Header) for log-level styling and an optional left-aligned timestamp string the backend renders in a dim colour. */
export interface TextDisplayLine {
  decoration?: Decoration;
  spans: StyledSpan[];
  timestamp?: string | null; // Optional timestamp prefix (e.g.
}

/** Standalone single-line framed text field. See the module doc. */
export interface TextField {
  clearable?: boolean; // Whether a clear (×) button shows when `Self::value` is non-empty.
  cursor?: number | null; // Byte offset into `Self::value`.
  has_focus?: boolean; // Whether the field has keyboard focus — same convention as `crate::Button::focused`: carries no "how did focus arrive" information.
  id: WidgetId;
  leading_icon?: Icon | null; // Icon painted inside the left bracket, before the text — e.g.
  placeholder?: string; // Shown, dimmed, in place of an empty `Self::value`.
  selection_anchor?: number | null; // Byte offset into `Self::value`.
  value?: string; // Current text.
}

/** Multi-line text input. Text is stored as one entry per line — empty lines are empty strings. Cursor is `(line, col)` in *char columns* (not bytes); the rasterisers convert as needed. */
export interface TextInput {
  cursor_col?: number; // Cursor column within the cursor line, in *char columns*.
  cursor_line?: number; // Cursor line index.
  has_focus?: boolean; // Whether the input has keyboard focus.
  id: WidgetId;
  lines: string[]; // One entry per logical line.
  placeholder?: string | null; // Optional placeholder shown when `lines` is empty or contains a single empty string.
  scroll_col?: number; // Horizontal scroll, in char columns.
  scroll_offset?: number; // First visible line index.
}

/** Optional time-of-day field shown alongside the date grid. `hour` is `0..=23`, `minute` is `0..=59`. */
export interface TimeOfDay {
  hour: number; // `0..=23`.
  minute: number; // `0..=59`.
}

/** One toggle in a `FieldKind::ToggleGroup`. */
export interface ToggleGroupItem {
  id: WidgetId;
  label: string;
  value: boolean;
}

/** Declarative description of a horizontal toolbar. */
export interface Toolbar {
  bg?: Color | null; // Optional background colour.
  buttons: ToolbarButton[];
  focused_index?: number | null; // Index of the keyboard-focused button within `Self::buttons`.
  id: WidgetId;
  orientation?: ToolbarOrientation; // Main-axis direction the buttons flow along.
  overflow?: ToolbarOverflow; // How items that don't fit the bar are handled.
  overflow_priorities?: ToolbarOverflowPriorities; // Per-item drop order for `ToolbarOverflow::Menu`, keyed by the owning `Action`/`Group`'s id.
  pin_trailing_overflow_to_origin?: boolean; // Which edge an over-long trailing group (the buttons after a `ToolbarButton::Spacer`) packs from — see `ToolbarLayoutOptions::pin_trailing_overflow_to_origin`.
  valign?: ToolbarVAlign; // Where button/label text sits within a slot taller than one text row.
}

/** One item in a `Toolbar`. */
export type ToolbarButton = ("Separator" | "Spacer") | _ToolbarButtonDict;

/** Semantic event a `Toolbar` click or Enter/Space activation stands for. */
export type ToolbarEvent = { ButtonClicked: _ToolbarEventButtonClicked; } | { GroupSelected: _ToolbarEventGroupSelected; } | { FieldChanged: _ToolbarEventFieldChanged; } | { FieldCommitted: _ToolbarEventFieldCommitted; } | { FieldCleared: _ToolbarEventFieldCleared; } | { MenuRequested: _ToolbarEventMenuRequested; } | { OverflowRequested: _ToolbarEventOverflowRequested; };

/** Main-axis width policy for a `ToolbarButton::Field`, passed to `Toolbar::layout_with_options` via `measure_button`/`tui_item_width`. */
export type ToolbarItemWidth = { Fixed: number; } | { Flex: _ToolbarItemWidthFlex; };

/** Main-axis direction a `Toolbar` lays its buttons out along, passed to `Toolbar::layout_with_options`. */
export type ToolbarOrientation = "Horizontal" | "Vertical";

/** How a `Toolbar` handles buttons that don't fit `bar_width`/`bar_height`, passed via `ToolbarLayoutOptions::with_overflow` and consumed by `Toolbar::layout_with_overflow` (`layout`/`layout_with_options` keep ignoring this field — see that method's own doc for why). */
export type ToolbarOverflow = "Clip" | "Wrap" | "Menu";

export type ToolbarOverflowPriorities = ToolbarOverflowPriorityEntry[];

/** One `ToolbarOverflowPriorities` registration, as it appears on the wire. Private: `ToolbarOverflowPriorities` keeps its own `(WidgetId, i32)` pair storage, and this is only the serde shape it maps each pair through. */
export interface ToolbarOverflowPriorityEntry {
  id: WidgetId;
  priority: number;
}

/** Vertical alignment of button/label text within a toolbar slot taller than one text row. */
export type ToolbarVAlign = "Top" | "Center" | "Bottom";

/** Events a `TreeView` emits back to the app. */
export type TreeEvent = { RowClicked: _TreeEventRowClicked; } | { RowDoubleClicked: _TreeEventRowDoubleClicked; } | { RowToggleExpand: _TreeEventRowToggleExpand; } | { SelectionChanged: _TreeEventSelectionChanged; } | { KeyPressed: _TreeEventKeyPressed; } | { SelectionSet: _TreeEventSelectionSet; } | { RowRenameChanged: _TreeEventRowRenameChanged; } | { RowRenameCommitted: _TreeEventRowRenameCommitted; } | { RowRenameCancelled: _TreeEventRowRenameCancelled; } | { RowActivated: _TreeEventRowActivated; } | { ScrollChanged: _TreeEventScrollChanged; } | { ContextMenuRequested: _TreeEventContextMenuRequested; };

/** One visible row in a `TreeView`. */
export interface TreeRow {
  badge?: Badge | null; // Right-aligned status indicator (e.g.
  decoration?: Decoration;
  edit?: TreeRowEditState | null; // When `Some`, backends render an inline text input in place of `text` and `badge`.
  icon?: Icon | null;
  indent: number; // Visual indent level in `style.indent` units.
  is_expanded?: boolean | null; // `None` marks a leaf; `Some(true)` marks an expanded branch; `Some(false)` marks a collapsed branch.
  path: number[];
  text: StyledText;
}

/** Inline editing state for a tree row. When present on a `TreeRow`, backends render a text input in place of the normal row label. */
export interface TreeRowEditState {
  cursor: number; // Cursor position as a byte offset into `text`.
  placeholder?: string | null; // Shown in muted style when `text` is empty (e.g.
  selection_anchor?: number | null; // Selection anchor as a byte offset.
  text: string;
}

/** Visual style configuration for a `TreeView`. */
export interface TreeStyle {
  bordered?: boolean; // Reserve a 1-cell/pixel margin on every edge of the tree's viewport for a decorative frame, mirroring `crate::primitives::list::ListView::bordered`.
  chevron_collapsed: string; // Chevron drawn for a collapsed branch.
  chevron_expanded: string; // Chevron drawn for an expanded branch.
  indent: number; // Cells / pixels per visual indent level.
  row_height?: number | null; // Host override for non-header row height, in the backend's native unit (pixels for GTK / macOS / Win-GUI).
  show_chevrons: boolean; // Draw expand/collapse chevrons on branches.
  show_scrollbar?: boolean; // Paint a vertical scrollbar when the rows overflow the viewport.
  vim_keys?: boolean; // Treat an unmodified `j` / `k` as Down / Up in the tree's own key handling.
}

/** Declarative description of a `TreeTable` widget: a `DataTable` plus per-row tree metadata. Every `DataTable` field keeps its existing meaning unchanged — selection, scroll, sort, focus, h-scroll, column overrides, footer, `bordered` and `striped` all behave exactly as they do on a plain `DataTable`. `tree` only ever adds the column-0 tree cell on top. */
export interface TreeTable {
  table: DataTable;
  tree: TreeTableNode[]; // Parallel to `table.rows`: `tree[i]` is `table.rows[i]`'s tree shape.
  vim_keys?: boolean; // `j`/`k` move the selection like Down/Up (while no Ctrl/Alt/Cmd is held), instead of starting a type-to-jump search.
}

/** A `"tree_table_controller"` extra: the hierarchical-model counterpart of `"tree_table"` (`TreeTable`/`quadraui::TreeTableNode`'s flat, host-flattened shape). Unlike every other additive primitive on this trait, decoding this is only ever the SEED for a `crate::engine::InteractionEngine`-cached `TreeTableController` — `crate::engine::InteractionEngine::sync_tree_tables` reads `nodes`/ `selected_id` exactly once, the first frame this `id` is seen (`Self::seed_controller`), then leaves the controller's own live expand/selection/sort state alone on every later frame, the same "seed once, then the richer controller owns it" rule that method's own doc gives for a `Form.scroll_offset`. `Self::paint` (the bare, non-interactive fallback every `ExtraPaint` impl gets painted with before that sync ever runs) builds a throwaway controller the same way, so the very first frame — before any controller is cached at all — still paints the full seeded model rather than nothing. */
export interface TreeTableControllerDescriptor {
  bordered?: boolean;
  columns?: Column[];
  folders_first?: boolean;
  has_focus?: boolean;
  id: WidgetId;
  nodes?: TreeTableControllerNode[];
  selected_id?: string | null;
  show_scrollbar?: boolean;
}

/** One node in a `"tree_table_controller"` extra's hierarchical model — the wire mirror of `TreeTableNodeData`, which has no `Deserialize` of its own (its fields are private; only its `TreeTableNodeData::leaf`/`TreeTableNodeData::branch`/ `TreeTableNodeData::lazy_branch` constructors are public), so a wire node decodes into this plain mirror first and `Self::into_node_data` then picks the matching constructor. `has_children: false` is always a `TreeTableNodeData::leaf` (`children` ignored); `has_children: true` with `children` present (including an empty list) is a `TreeTableNodeData::branch`; `has_children: true` with `children` absent is a `TreeTableNodeData::lazy_branch` — the same three-way split `quadraui::compose::tree_table_controller`'s own module doc describes for *Lazy loading*. */
export interface TreeTableControllerNode {
  cells?: StyledText[];
  children?: TreeTableControllerNode[] | null;
  has_children?: boolean;
  icon?: Icon | null;
  id: string;
}

/** Wire-shaped mirror of `TreeTableControllerEvent` — the same field shapes, but `Serialize`/`Deserialize` (`TreeTableControllerEvent` itself has neither; it's an in-crate-only `quadraui::compose` type), and `Consumed`/`Ignored` dropped: `InteractionEngine::handle` only ever calls `EventSink::dispatch_tree_table_controller` for the five variants below, folding `Consumed`/`Ignored` straight into its own `Reaction` instead (see that method's own `TreeTableController` routing blocks). */
export type TreeTableControllerWireEvent = { RowSelected: _TreeTableControllerWireEventRowSelected; } | { RowActivated: _TreeTableControllerWireEventRowActivated; } | { ToggleExpand: _TreeTableControllerWireEventToggleExpand; } | { ChildrenRequested: _TreeTableControllerWireEventChildrenRequested; } | { SortChanged: _TreeTableControllerWireEventSortChanged; };

/** Events a `TreeTable` emits back to the app. Row events carry the row's `TreePath` alongside its flat index. */
export type TreeTableEvent = { SortChanged: _TreeTableEventSortChanged; } | { RowActivated: _TreeTableEventRowActivated; } | { RowSelected: _TreeTableEventRowSelected; } | { RowDoubleClicked: _TreeTableEventRowDoubleClicked; } | { Scroll: _TreeTableEventScroll; } | { ScrollChanged: _TreeTableEventScrollChanged; } | { ColumnResized: _TreeTableEventColumnResized; } | { SelectionSet: _TreeTableEventSelectionSet; } | { ToggleExpanded: _TreeTableEventToggleExpanded; } | { ChildrenRequested: _TreeTableEventChildrenRequested; } | { ContextMenuRequested: _TreeTableEventContextMenuRequested; };

/** Per-row tree metadata for one `TreeTable` row, parallel to `DataTable::rows` on `TreeTable::table`. */
export interface TreeTableNode {
  children_pending?: boolean; // A branch whose children the app has not supplied yet: expanding it reports `TreeTableEvent::ChildrenRequested` as well as the expand itself.
  icon?: Icon | null; // Optional leading icon, painted between the chevron and the label.
  indent: number; // Visual indent level, in the backend's indent unit.
  is_expanded?: boolean | null; // `None` marks a leaf; `Some(true)`/`Some(false)` an expanded/collapsed branch.
  path: number[]; // This row's path.
  placeholder?: boolean; // A row standing in for a pending branch's children while they load (typically a dim `…`): painted like any row, but never selected, activated or expanded.
}

/** Declarative description of a `TreeView` widget. */
export interface TreeView {
  has_focus?: boolean; // Whether this tree currently holds keyboard focus.
  id: WidgetId;
  rows: TreeRow[]; // Pre-flattened, pre-expanded rows in visual order.
  scroll_offset?: number; // How many rows have been scrolled past (app-owned in v1; primitive-owned scroll state with `ScrollState::id(widget_id)` is a later stage per `docs/UI_CRATE_DESIGN.md` §3.1).
  selected_path?: number[] | null;
  selection_mode: SelectionMode;
  style: TreeStyle;
}

export interface TreeViewLeaf {
  has_focus?: boolean; // Whether this tree currently holds keyboard focus.
  id: WidgetId;
  rows: TreeRow[]; // Pre-flattened, pre-expanded rows in visual order.
  scroll_offset?: number; // How many rows have been scrolled past (app-owned in v1; primitive-owned scroll state with `ScrollState::id(widget_id)` is a later stage per `docs/UI_CRATE_DESIGN.md` §3.1).
  selected_path?: number[] | null;
  selection_mode: SelectionMode;
  style: TreeStyle;
  items_window?: ItemsWindow | null;
  scroll_px?: number;
}

